import{_ as o,C as i,c as n,o as a,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Price lists","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/sales/products-prices/price-lists.md","filePath":"master/sales/sales/products-prices/price-lists.md","lastUpdated":1791902625000}'),l={name:"master/sales/sales/products-prices/price-lists.md"};function c(g,e,p,u,h,d){const r=i("ImagePopup");return a(),n("div",null,[e[0]||(e[0]=t('<h1 id="price-lists" tabindex="-1">Price lists <a class="header-anchor" href="#price-lists" aria-label="Permalink to &quot;Price lists&quot;">​</a></h1><p>A price list holds pricing rules for a currency. Use price lists to sell the same product at different prices, for example to wholesale and retail customers. You can pick a price list on a quotation.</p><blockquote><p><strong>In simple words:</strong> A price list is a set of rules that decide the selling price.</p></blockquote><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The <strong>Price Lists</strong> page shows only when the feature is on.</p><ol><li>Go to <code>Sales → Settings → Manage Products</code>.</li><li>Turn on <strong>Price Lists</strong> (Allow products to be sold at prices set by a price list).</li><li>Click <strong>Save changes</strong>.</li></ol>',6)),s(r,{src:"/images1/sales/set_products.png",alt:"Manage Products settings with the Price Lists option turned on"}),e[1]||(e[1]=t('<h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Go to <code>Sales → Products → Price Lists</code>. The list shows <strong>Price List</strong>, <strong>Currency</strong>, <strong>Company</strong>, <strong>Rules</strong> and <strong>Active</strong>. You can filter by <strong>Active</strong> and <strong>Currency</strong>. When nothing exists, it shows <strong>No Price Lists</strong>.</p>',2)),s(r,{src:"/images1/sales/pricelists.png",alt:"Price Lists list showing India Price List (INR) with its currency and company"}),e[2]||(e[2]=t('<h2 id="create-a-price-list" tabindex="-1">Create a price list <a class="header-anchor" href="#create-a-price-list" aria-label="Permalink to &quot;Create a price list&quot;">​</a></h2><ol><li><p>Go to <code>Sales → Products → Price Lists</code>.</p></li><li><p>Click <strong>New Price List</strong>.</p></li><li><p>Fill in <strong>General Information</strong>:</p><ul><li><strong><em>Price List Name:</em></strong> Enter a name. This field is required.</li><li><strong><em>Currency:</em></strong> Choose an active currency. This field is required.</li><li><strong><em>Company:</em></strong> Choose the company.</li><li><strong><em>Active:</em></strong> Turn on to make the list available. It is on by default.</li></ul></li><li><p>Add rules under <strong>Price Rules</strong>, as described below.</p></li><li><p>Click <strong>Create</strong>.</p></li></ol>',2)),s(r,{src:"/images1/sales/pricelist_form.png",alt:"New Price List form with General Information and Price Rules"}),e[3]||(e[3]=t('<h2 id="add-a-price-rule" tabindex="-1">Add a price rule <a class="header-anchor" href="#add-a-price-rule" aria-label="Permalink to &quot;Add a price rule&quot;">​</a></h2><p>The first rule that matches a product decides its price. More specific rules win over broader ones.</p><ol><li><p>Under <strong>Price Rules</strong>, click <strong>Add Rule</strong>.</p></li><li><p>Fill in the rule window:</p><ul><li><strong><em>Apply To:</em></strong> Choose <strong>All Products</strong>, <strong>Category</strong>, <strong>Product</strong> or <strong>Variant</strong>. Then choose the category, product or variant.</li><li><strong><em>Min Qty:</em></strong> Set the smallest quantity for the rule.</li><li><strong><em>Validity Period</em></strong> and <strong><em>End Date:</em></strong> Set when the rule is active.</li><li><strong><em>Price Type:</em></strong> Choose <strong>Fixed Price</strong>, <strong>Discount</strong> or <strong>Formula</strong>.</li></ul></li><li><p>Complete the fields for the price type:</p><ul><li><strong>Fixed Price:</strong> Enter the <strong>Fixed Price</strong>.</li><li><strong>Discount:</strong> Enter the <strong>Discount</strong> percentage and choose what it is based on. Use a negative value to apply a mark-up.</li><li><strong>Formula:</strong> Choose the <strong>Based price</strong>: <strong>Sales Price</strong>, <strong>Cost</strong> or <strong>Other Price List</strong>. Then set <strong>Discount</strong> or <strong>Markup</strong>, <strong>Round off to</strong>, <strong>Extra Fee</strong>, <strong>Min. Margin</strong> and <strong>Max. Margin</strong>.</li></ul></li><li><p>Save the rule.</p></li></ol><p>The rules table shows <strong>Apply On</strong>, <strong>Applies To</strong>, <strong>Min. Quantity</strong>, <strong>Compute Price</strong>, <strong>Price</strong> and <strong>Period</strong>. Click <strong>Edit Rule</strong> on a row to change it.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To end prices at 9.99, set <strong>Round off to</strong> 10.00 and set <strong>Extra Fee</strong> to -0.01.</p></div>',5)),s(r,{src:"/images1/sales/pricelist_rule_window.png",alt:"Add Rule window with product, fixed price, minimum quantity and validity dates"}),e[4]||(e[4]=t('<h2 id="use-a-price-list-on-a-quotation" tabindex="-1">Use a price list on a quotation <a class="header-anchor" href="#use-a-price-list-on-a-quotation" aria-label="Permalink to &quot;Use a price list on a quotation&quot;">​</a></h2><p>On a quotation, choose the list in <strong>Price List</strong>. The field shows only when <strong>Price Lists</strong> is on. When you choose a customer, Aureus fills the price list that is saved on that customer, if there is one.</p><p>The quotation then takes the <strong>currency of the price list</strong>. Every product line is priced again at once, so you do not have to change anything by hand. If you change the price list later, the lines are priced again.</p><h3 id="how-the-price-on-a-line-is-worked-out" tabindex="-1">How the price on a line is worked out <a class="header-anchor" href="#how-the-price-on-a-line-is-worked-out" aria-label="Permalink to &quot;How the price on a line is worked out&quot;">​</a></h3><p>Products always keep their <strong>Price</strong> in your company&#39;s base currency, for example USD. For each line, Aureus looks at the price list rules:</p><ol><li><strong>A rule matches the product.</strong> The rule decides the price. <ul><li><strong>Fixed Price:</strong> The price you typed in the rule is used as it is. Type it in the currency of the price list.</li><li><strong>Discount</strong> or <strong>Formula:</strong> The percentage or formula is applied to the sales price (or cost, or another price list) after it has been converted to the price list currency.</li></ul></li><li><strong>No rule matches.</strong> Aureus converts the product&#39;s normal sales price to the price list currency with the exchange rate.</li></ol><p>To sell in another currency, set the currency of the price list and add an exchange rate. The full steps, with an example and screenshots, are in <a href="./sell-in-other-currencies.html">Sell in other currencies</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./sell-in-other-currencies.html">Sell in other currencies</a></li><li><a href="./../quotations-orders/create-quotation.html">Create a quotation</a></li><li><a href="./discounts-margins.html">Discounts and margins</a></li></ul>',9))])}const P=o(l,[["render",c]]);export{_ as __pageData,P as default};
